/*TODO*/ select mbatpr.baseymd ,mbatpr.update_tm ,mbatpr.route_id ,mbatpr.oper_seq ,mbatpr.st_sta_id ,mbatpr.arr_sta_id ,mbatpr.st_tm ,mbatpr.arr_tm ,mbatpr.el_tm from mrt_bus_arvl_time_prdctn_rslt mbatpr inner join ( select MAX(mbatpr.update_tm) as rct_update_tm , mbatpr.baseymd , mbatpr.route_id, mbatpr.st_sta_id , mbatpr.arr_sta_id , mbatpr.oper_seq from mrt_bus_arvl_time_prdctn_rslt mbatpr group by mbatpr.baseymd ,mbatpr.route_id,mbatpr.st_sta_id ,mbatpr.arr_sta_id,mbatpr.oper_seq ) RCT on RCT.baseymd = mbatpr.baseymd and RCT.ROUTE_ID = mbatpr.route_id and RCT.ST_STA_ID = mbatpr.st_sta_id and RCT.ARR_STA_ID = mbatpr.arr_sta_id and RCT.oper_seq = mbatpr.oper_seq and RCT.rct_update_tm = mbatpr.update_tm where mbatpr.route_id = #{routeId} and mbatpr.arr_sta_id = #{edStationId}
AND TO_CHAR(TO_DATE(mbatpr.baseymd,'YYYYMMDD'), 'YYYY') = #{searchYear}
AND TO_CHAR(TO_DATE(mbatpr.baseymd,'YYYYMMDD'), 'YYYY-MM-DD') = #{startDate}
